# ================================================================== clase 4
L(OA, 4,
  "Este cuaderno y un lápiz. Los textos están escritos en cada ejercicio; los errores son parte de la práctica.",
  "Aprenderé a reconocer y corregir usos inadecuados de pronombres personales y reflejos, conjugaciones, participios irregulares y concordancias.",
  ["Sé qué es un verbo y un sustantivo.", "Sé identificar el sujeto de una oración."],
  ["Al revisar las oraciones se buscan errores de concordancia, es decir, de acuerdo entre palabras. El verbo concuerda con el sujeto en número y persona: «Los estudiantes llegaron» y no «Los estudiantes llegó». El artículo y el adjetivo concuerdan con el sustantivo en género y número: «las casas blancas» y no «las casas blancos». Revisa también los verbos: «dijiste» y no «dijistes»; «hubo muchos problemas» y no «hubieron muchos problemas».",
   "Los participios irregulares no terminan en -ado ni en -ido: abrir, abierto; cubrir, cubierto; decir, dicho; escribir, escrito; hacer, hecho; poner, puesto; romper, roto; ver, visto; volver, vuelto. Son incorrectos «rompido», «escribido», «ponido» o «volvido». Los pronombres también se revisan: los reflejos (me, te, se, nos) deben concordar con el sujeto: «yo me lavé», «ellos se lavaron». Con preposición se dice «entre tú y yo» y «para mí»; con «con» se dice «conmigo». El complemento de persona de verbos como «decir», «dar» o «pedir» lleva «le» o «les»: «Les dije a mis amigas que vinieran», y no «Lo dije a mis amigas» ni «Las dije».",
   "Para revisar, lee oración por oración. Primero busca el verbo y pregunta ¿quién lo realiza? para comprobar la concordancia. Luego revisa artículo, sustantivo y adjetivo. Después, los verbos compuestos (he escrito, había visto). Cuando dudes, reemplaza por otro verbo o sustantivo cuya forma conozcas."],
  [("concordancia", "acuerdo en género, número o persona entre palabras"), ("participio irregular", "participio que no termina en -ado ni -ido, como «roto» o «escrito»"), ("pronombre reflejo", "pronombre que indica que la acción recae en quien la realiza, como «me lavé»"), ("sujeto", "palabra o grupo que realiza la acción del verbo"), ("conjugación", "forma que toma el verbo según persona, número y tiempo")],
  [("Concordancia sujeto-verbo", "Corrige: «Los estudiantes de octavo presentó el informe». ",
    ["Pregunta: ¿quién presentó? Los estudiantes de octavo, plural.", "El verbo debe ir en plural.", "Versión: Los estudiantes de octavo presentaron el informe."], "Los estudiantes de octavo presentaron el informe"),
   ("Participio y pronombre", "Corrige: «Yo he rompido el cuaderno y entre tu y yo, se lo he escribido a ella». ",
    ["«Rompido» es incorrecto: roto.", "«Escribido» es incorrecto: escrito.", "«Entre tú y yo» lleva tilde en «tú». Versión: He roto el cuaderno y, entre tú y yo, se lo he escrito a ella."], "He roto el cuaderno y, entre tú y yo, se lo he escrito a ella")],
  [("Decir «hubieron muchos problemas».", "«Hubo» no cambia de número cuando significa «existir».", "Usa «hubo muchos problemas»."),
   ("Cambiar el participio por una forma regular.", "Los participios irregulares no admiten «-ido» ni «-ado».", "Memoriza los más frecuentes.")],
  ([E("¿Cuál es correcta? (a) Los niños jugaron. (b) Los niños jugó. (c) Los niños jugaste.", "(a)", "El verbo concuerda con el sujeto plural."),
    E("¿Cuál es el participio de «romper»?", "Roto", "Es un participio irregular."),
    E("¿Cuál es correcta? (a) las casas blancas. (b) las casas blancos. (c) los casas blanca.", "(a)", "El adjetivo concuerda con el sustantivo.")],
   [E("¿Cuál es correcta? (a) Hubo muchas personas. (b) Hubieron muchas personas. (c) Habemos muchas personas.", "(a)", "«Hubo» se usa en singular."),
    E("¿Cuál es el participio de «escribir»?", "Escrito", "Es un participio irregular."),
    E("¿Cuál es correcta? (a) Dijiste la verdad. (b) Dijistes la verdad. (c) Dijites la verdad.", "(a)", "La segunda persona singular del pretérito termina en -iste.")],
   [E("Corrige: «La brigada preparan el afiche». ¿Cuál es correcta? (a) La brigada prepara el afiche. (b) La brigada preparan los afiche. (c) La brigada prepararon el afiche.", "(a)", "Sujeto singular: «brigada»."),
    E("Completa con el participio: «Hemos ______ (ver) el informe». ", "Visto", "El participio de ver es «visto»."),
    E("¿Cuál es correcta? (a) Entre tú y yo. (b) Entre tú y mí. (c) Entre ti y yo.", "(a)", "Con «entre» se usan los pronombres de sujeto «tú» y «yo».")],
   [E("«Yo se lavó las manos» tiene un error de concordancia. ¿Cuál es la forma correcta?", "Yo me lavé las manos", "El pronombre reflejo debe concordar con «yo»."),
    E("Corrige: «Los problemas son difícil». ¿Cuál es correcta?", "Los problemas son difíciles", "El adjetivo concuerda en número."),
    E("Corrige: «Hubieron demasiados errores en el texto». ¿Cuál es correcta?", "Hubo demasiados errores en el texto", "«Hubo» no cambia al plural.")],
   [E("Corrige este texto de ejemplo: «Ayer la brigada prepara el afiche. Ellos habían rompido el primer borrador y lo escribió de nuevo». Escribe una versión correcta.", "Ayer la brigada preparó el afiche. Habían roto el primer borrador y lo escribieron de nuevo", "Se corrigen tiempo, participio y concordancia."),
    E("Corrige: «Yo lo dije a mis amigas que vinieran». ¿Cuál versión es más adecuada? (a) Yo les dije a mis amigas que vinieran. (b) Yo lo dije a mis amigas. (c) Yo las dije a mis amigas.", "(a)", "El pronombre de objeto indirecto plural es «les».")]),
  [E("Revisas la carta a la directora y lees «los estudiantes ha escribido una petición». ¿Cuál es la corrección? (a) Los estudiantes han escrito una petición. (b) Los estudiantes han escribido una petición. (c) Los estudiantes ha escrito una petición.", "(a)", "Corrige la concordancia y el participio.")],
  [E("Nombra tres participios irregulares.", "Por ejemplo: roto, escrito y hecho", "Son participios irregulares."),
   E("¿Con qué concuerda el verbo?", "Con el sujeto", "En número y persona."),
   E("¿Se dice «entre tú y yo» o «entre tú y mí»?", "Entre tú y yo", "Con «entre» se usan los pronombres de sujeto.")],
  ("Corrige este párrafo de ejemplo: «Ayer la brigada prepara el afiche. La brigada, que tenían dos borradores, lo mostraron: “Falta la fuente” dijo Inés. Después el equipo había corregido el afiche y mañana lo presentó». Reescribe todo el párrafo con los verbos y las concordancias correctas, y anota cuatro correcciones que hiciste con su razón.",
   "Ayer la brigada preparó el afiche. La brigada, que tenía dos borradores, los mostró. —Falta la fuente —dijo Inés—. Después, el equipo corrigió el afiche y mañana lo presentará. Correcciones: «prepara» a «preparó» (tiempo pasado); «tenían» a «tenía» (sujeto singular «la brigada»); «mostraron» a «mostró»; «presentó» a «presentará» (mañana, tiempo futuro).",
   ["corrige la concordancia", "ajusta los tiempos verbales", "explica cuatro correcciones"], ["párrafo corregido y lista de cuatro correcciones en el cuaderno"],
   ["corregir solo la ortografía", "no explicar las correcciones"], "Compara tu versión con la de otra persona y revisa si ambas mantuvieron los tiempos coherentes."),
  "Escribe tres oraciones usando los participios «roto», «escrito» y «visto».",
  "Inventa un párrafo con cinco errores de concordancia y pídele a otra persona que los corrija.")

# ================================================================== clase 5
L(OA, 5,
  "Este cuaderno y un lápiz. Los textos y las descripciones de herramientas están escritos en cada ejercicio.",
  "Aprenderé a editar la ortografía y la presentación de un texto, y a usar eficazmente las herramientas de un procesador de textos.",
  ["Sé revisar la concordancia.", "Sé las reglas básicas de tildes y mayúsculas."],
  ["Editar es la etapa final: se corrige la ortografía, la puntuación y la presentación. En ortografía se revisa la tilde (palabras agudas, graves y esdrújulas), las letras que suenan igual (b/v, c/s/z, g/j, h), las mayúsculas (inicio de oración, nombres propios) y la tilde diacrítica («sí» y «si», «más» y «mas», «él» y «el», «tú» y «tu», «sé» del verbo saber y «se»). En puntuación se revisa el punto, la coma (en enumeraciones y para separar un vocativo o una explicación), los signos de interrogación y exclamación de apertura y cierre, y la raya del diálogo.",
   "La presentación comprende el título, los párrafos separados, los márgenes, una letra legible y la limpieza. Un procesador de textos ayuda con varias herramientas: el corrector ortográfico subraya posibles errores, pero no los entiende todos (puede aceptar «sé» en lugar de «se» porque ambas existen); la función de buscar y reemplazar cambia una palabra en todo el texto; los estilos de título dan jerarquía; el interlineado (por ejemplo, 1,5) mejora la lectura; la numeración de páginas ordena; y el control de cambios o los comentarios muestran qué se modificó.",
   "El corrector no reemplaza tu lectura. Después de usarlo, relee en voz alta y verifica los casos dudosos con un diccionario. Guarda el archivo con un nombre que indique la versión (por ejemplo, «informe_v2») para conservar la anterior. Imprime o revisa la vista previa para comprobar la presentación final."],
  [("editar", "corregir ortografía, puntuación y presentación del texto final"), ("tilde diacrítica", "tilde que distingue palabras iguales, como «sí» y «si»"), ("corrector ortográfico", "herramienta que subraya posibles errores de escritura"), ("control de cambios", "herramienta que muestra las modificaciones hechas a un texto"), ("estilo de título", "formato que da jerarquía a los títulos de un documento")],
  [("Corregir ortografía", "Corrige: «el nino dijo que si queria mas pan, pero yo se que no tenia». ",
    ["Mayúscula inicial: «El».", "Tildes: niño, sí, quería, más, sé, tenía. Falta puntuación.", "Versión: El niño dijo que sí quería más pan, pero yo sé que no tenía."], "El niño dijo que sí quería más pan, pero yo sé que no tenía"),
   ("Elegir la herramienta", "Quieres cambiar «colegio» por «escuela» en todo un informe de 5 páginas. ¿Qué herramienta usas?",
    ["Hacerlo a mano toma tiempo y puede dejar errores.", "La función de buscar y reemplazar lo hace en todo el texto.", "Después hay que revisar que no cambie palabras como «colegiales»."], "Buscar y reemplazar, y revisar el resultado")],
  [("Confiar solo en el corrector ortográfico.", "No detecta todos los errores, como «sí» y «si» bien escritas pero mal usadas.", "Relee en voz alta y usa diccionario."),
   ("Entregar un texto sin título ni párrafos.", "Dificulta la lectura.", "Revisa la presentación.")],
  ([E("¿Qué es editar?", "Corregir ortografía, puntuación y presentación en la versión final", "Es la última etapa del proceso."),
    E("¿Cuál lleva tilde diacrítica por ser afirmación? (a) sí. (b) si. (c) se.", "(a)", "«Sí» afirmativo lleva tilde."),
    E("¿Qué signo se escribe al inicio y al final de una pregunta?", "Los signos de interrogación de apertura y cierre", "En español van ¿ y ?.")],
   [E("¿Cuál se escribe correctamente? (a) Ellos sí vendrán. (b) Ellos si vendran. (c) Ellos sí vendran.", "(a)", "Lleva tilde en «sí» y «vendrán»."),
    E("¿Qué herramienta muestra qué cambió entre dos versiones?", "El control de cambios", "Registra las modificaciones."),
    E("¿Para qué sirve el interlineado de 1,5?", "Para mejorar la legibilidad", "Separa las líneas y facilita la lectura.")],
   [E("Elige la oración bien escrita: (a) ¿Cuándo llegas, tú o él? (b) cuando llegas tu o el. (c) ¡Cuando llegas tú o él?", "(a)", "Tiene signos y tildes correctas."),
    E("Completa con «más» o «mas»: «Quiero ______ agua». ", "Más", "Aquí indica cantidad de agua."),
    arith("Tu informe de 5 páginas tiene 3 errores por página. ¿Cuántos errores debes revisar en total?", "5*3", "Se multiplican las páginas por los errores por página.", " errores")],
   [E("Escribes «tu sabes si el vino» y el corrector no subraya nada. ¿Por qué ocurre, y cómo debe escribirse?", "Porque «tu» y «el» existen como palabras y el corrector no entiende el sentido; debe escribirse «tú sabes si él vino»", "Ambas formas son válidas aisladamente, pero aquí faltan las tildes."),
    E("Dos versiones: «informe.docx» y «informe_v2.docx». ¿Qué ventaja tiene guardar con otro nombre?", "Conserva la versión anterior", "Permite volver atrás.")],
   [E("Revisa y corrige: «¿Que haces tu aqui. dijo maria». Escribe la versión correcta.", "—¿Qué haces tú aquí? —dijo María", "Se corrigen signos, tildes, mayúsculas y la raya."),
    E("Escribe una regla para decidir entre «si» y «sí».", "«Sí» con tilde es afirmación; «si» sin tilde expresa condición", "Es la regla de la tilde diacrítica.")]),
  [E("Terminaste un informe y quieres entregarlo mañana. ¿Qué haces hoy? (a) Corregir con el corrector, releer en voz alta y revisar la presentación. (b) Entregarlo sin mirar. (c) Entregarlo apenas el corrector no marque errores.", "(a)", "Se edita con varias estrategias.")],
  [E("Nombra una herramienta de procesador de textos.", "Por ejemplo: corrector ortográfico, buscar y reemplazar o control de cambios", "Son herramientas de edición."),
   E("¿Qué se debe hacer tras usar el corrector?", "Releer y verificar los casos dudosos", "No detecta todo."),
   E("¿Qué significa guardar con otro nombre?", "Conservar la versión anterior y crear una nueva", "Así se puede recuperar la anterior.")],
  ("Edita este texto de ejemplo, escrito sin cuidado: «los estudiantes de octavo organizaron una feria del libro. participaron 20 cursos. fue un exito. quien quiera mas informacion puede preguntar a la profesora». Corrige mayúsculas, tildes, puntuación y presentación (título y párrafos) y anota tres herramientas de un procesador de textos que usarías y para qué.",
   "Feria del libro. Los estudiantes de octavo organizaron una feria del libro. Participaron 20 cursos. Fue un éxito. Quien quiera más información puede preguntar a la profesora. Herramientas: corrector ortográfico (señalar errores), estilo de título (dar jerarquía al título) y vista previa (comprobar la presentación).",
   ["corrige mayúsculas y tildes", "agrega título y puntuación", "nombra tres herramientas con su función"], ["texto corregido y tres herramientas en el cuaderno"],
   ["no revisar las mayúsculas", "nombrar herramientas sin explicar su uso"], "Intercambia tu texto con otra persona y revisa si quedó algún error."),
  "Escribe una oración con «sí» y otra con «si» usando la tilde correctamente.",
  "Escribe una lista de cotejo de seis puntos para editar un texto antes de entregarlo.")

# ================================================================== clase 6
L(OA, 6,
  "Este cuaderno y un lápiz. Las versiones y los registros de cambios están escritos en cada ejercicio.",
  "Aprenderé a documentar los cambios hechos a un texto, a justificar cada uno y a publicar la versión final de manera responsable.",
  ["Sé planificar, revisar y editar un texto.", "Sé qué es una versión de un texto."],
  ["Documentar los cambios es dejar registro de lo que modificaste en cada versión y por qué. Un registro simple tiene cuatro columnas: versión, qué cambió, por qué y quién lo sugirió (si fue una compañera, el profesor o tú). Por ejemplo: «v2: agregué un conector entre los párrafos 2 y 3 porque las ideas estaban sueltas (sugerido por mi compañera Ana)». Así puedes explicar cómo mejoró el texto.",
   "Los cambios pueden ser de distinto tipo: de contenido (agregar información), de organización (reordenar párrafos), de cohesión (agregar conectores), de gramática (concordancia, tiempos), de vocabulario (precisión) y de ortografía o presentación. Conviene agruparlos por tipo. Si cambias una frase, conserva la anterior en la versión previa por si necesitas volver atrás.",
   "Publicar es compartir la versión final con la audiencia: impresa, en un diario mural, en el boletín, en una carpeta digital del curso. Antes de publicar, usa la lista de cotejo y verifica que el texto no contenga datos personales ni imágenes sin autorización. Después, guarda un registro de las versiones. Reflexionar sobre qué cambios fueron más útiles te ayuda a escribir mejor la próxima vez."],
  [("versión", "estado de un texto en un momento del proceso"), ("registro de cambios", "tabla que anota qué se cambió y por qué"), ("lista de cotejo", "lista de preguntas para comprobar un texto"), ("publicar", "compartir la versión final con una audiencia"), ("datos personales", "información que identifica a una persona, como su dirección o teléfono")],
  [("Registrar un cambio", "Versión 1: «Reciclamos. Es bueno». Versión 2: «Reciclamos papel y plástico porque así reducimos la basura del colegio». Escribe una entrada del registro.",
    ["Qué cambió: se agregó qué se recicla y una razón.", "Por qué: la primera versión era vaga.", "Entrada: v2: especifiqué el material y agregué una razón porque la idea era vaga."], "v2: especifiqué el material y agregué una razón porque la idea era vaga"),
   ("Clasificar cambios", "Cambios hechos: a) cambié «cosa» por «herramienta»; b) agregué «por eso» entre dos oraciones; c) corregí «hubieron» por «hubo»; d) moví el párrafo de ejemplos al final. Clasifícalos por tipo.",
    ["a) vocabulario; b) cohesión.", "c) gramática (concordancia).", "d) organización."], "a vocabulario; b cohesión; c gramática; d organización")],
  [("Cambiar el texto sin dejar registro.", "No se sabe qué se modificó ni por qué.", "Anota versión, cambio y razón."),
   ("Publicar con datos personales.", "Puede perjudicar la privacidad.", "Elimina direcciones, teléfonos o imágenes sin autorización.")],
  ([E("¿Qué es un registro de cambios?", "Una tabla que anota qué se cambió y por qué", "Permite explicar cómo mejoró el texto."),
    E("Cambiar «hubieron» por «hubo» es un cambio de... (a) gramática. (b) presentación. (c) contenido.", "(a)", "Corrige la concordancia."),
    E("¿Qué se debe verificar antes de publicar?", "Que no haya datos personales ni imágenes sin autorización", "Se protege la privacidad.")],
   [E("Agregar «por eso» para unir dos oraciones es un cambio de... (a) cohesión. (b) ortografía. (c) vocabulario.", "(a)", "Los conectores unen oraciones."),
    E("Cambiar «hacer» por «elaborar» es un cambio de... (a) vocabulario. (b) puntuación. (c) organización.", "(a)", "Mejora la precisión de la palabra."),
    E("¿Qué columnas puede tener un registro?", "Versión, qué cambió, por qué y quién lo sugirió", "Son las cuatro columnas de la clase.")],
   [E("Clasifica: 1) reordenar los párrafos 2 y 3; 2) agregar una tilde; 3) sumar un dato nuevo. ¿Cuál es el tipo de cada uno?", "1 organización; 2 ortografía; 3 contenido", "Cada cambio corresponde a un tipo distinto."),
    E("Un texto tiene 10 cambios en el registro y 4 son de ortografía. ¿Cuántos no son de ortografía?", "6", "10 − 4 = 6."),
    arith("En 3 versiones se hicieron 5, 4 y 2 cambios. ¿Cuántos cambios hubo en total?", "5+4+2", "Se suman los cambios de cada versión.", " cambios")],
   [E("Una compañera sugiere un cambio que mejora el texto, pero no lo anotas. ¿Qué problema hay?", "No queda registro de quién lo sugirió ni por qué se hizo", "El registro debe incluir el origen del cambio."),
    E("Publicas tu texto con tu teléfono al final, sin necesidad. ¿Qué riesgo hay?", "Expones datos personales", "El teléfono no es necesario.")],
   [E("Completa la entrada: «v3: cambié ______ porque ______». Con el cambio de «cosa» por «herramienta».", "Por ejemplo: «cambié “cosa” por “herramienta” porque la palabra era vaga»", "Indica el cambio y su razón."),
    E("¿Para qué sirve reflexionar sobre los cambios útiles?", "Para escribir mejor el próximo texto", "Permite aprender del proceso.")]),
  [E("Vas a publicar tu informe en el diario mural. ¿Qué haces antes? (a) Usar la lista de cotejo, quitar datos personales y guardar el registro de versiones. (b) Pegar el primer borrador. (c) Borrar tus notas.", "(a)", "Se revisa, se protege la privacidad y se registra.")],
  [E("Nombra tres tipos de cambios.", "Por ejemplo: de contenido, de cohesión y de ortografía", "Son tipos de cambios."),
   E("¿Qué debe llevar cada entrada de registro?", "El cambio y su razón", "Así se puede justificar cada cambio."),
   E("¿Dónde puede publicarse un texto escolar?", "En un diario mural, un boletín o una carpeta del curso", "Son audiencias reales.")],
  ("Con estas dos versiones de ejemplo, completa un registro de cuatro cambios. Versión 1: «Hubieron muchos estudiantes en la feria. fue una cosa buena. Todos compraron». Versión 2: «Hubo muchos estudiantes en la feria. Fue una actividad exitosa: más de 100 personas compraron libros». Para cada cambio, escribe tipo, qué cambió y por qué. Después escribe una frase de reflexión.",
   "1) Gramática: «hubieron» por «hubo», porque «hubo» no cambia de número. 2) Ortografía: mayúscula en «Fue». 3) Vocabulario: «cosa buena» por «actividad exitosa», para ser más preciso. 4) Contenido: se agregó «más de 100 personas compraron libros», para dar evidencia. Reflexión: el cambio más útil fue agregar evidencia porque hace el texto más convincente.",
   ["identifica cuatro cambios", "los clasifica", "justifica cada uno y reflexiona"], ["registro de cuatro filas y una frase en el cuaderno"],
   ["clasificar mal un cambio", "no justificar"], "Comparte tu registro con otra persona y revisa si coincide en la clasificación."),
  "Escribe una entrada de registro para un cambio que hayas hecho a un texto reciente.",
  "Crea un modelo de registro de cambios con cuatro columnas para tus próximos textos.")
